INSERT IGNORE INTO `site_word` (`name`, `lang`, `txt`) VALUES ('abc hint', 'kz', 'Тізім таңдалған көрсеткіш бойынша азаю ретімен. «Жиынтық» — осы тағамға дейінгілердің бірге алған үлесі. Оң жақтағы үш әріп: түсім, саны, маржа бойынша класы (мысалы, «A A C» — көп сатылады, бірақ пайдасы аз). Маржа = түсім − себес (Тағамдар ▸ Себес), жеңілдік пен жеткізу ақысы есептелмейді.'), ('abc hint', 'ru', 'Список отсортирован по выбранному показателю по убыванию. «Накопительно» — общая доля этого блюда и всех блюд выше. Три буквы справа: класс по выручке, количеству и марже (например, «A A C» — продаётся много, но прибыли мало). Маржа = выручка − себестоимость (Блюда ▸ Себестоимость), скидки и доставка не учитываются.'), ('abc hint', 'en', 'The list is sorted by the selected measure, highest first. “Cumulative” is the combined share of this dish and all dishes above it. The three letters on the right are the class by revenue, quantity and margin (for example, “A A C” sells a lot but earns little). Margin = revenue − cost (Dishes ▸ Cost sheet); discounts and delivery fees are not included.'), ('abc hint', 'uz', 'Ro‘yxat tanlangan ko‘rsatkich bo‘yicha kamayish tartibida. «Jamlanma» — shu taom va undan yuqoridagilarning umumiy ulushi. O‘ngdagi uch harf: tushum, soni va marja bo‘yicha sinf (masalan, «A A C» — ko‘p sotiladi, lekin foydasi kam). Marja = tushum − tannarx (Taomlar ▸ Tannarx), chegirma va yetkazib berish hisobga olinmaydi.'), ('abc hint', 'ky', 'Тизме тандалган көрсөткүч боюнча азаюу тартибинде. «Жыйынтык» — ушул тамак жана андан жогоркулардын жалпы үлүшү. Оң жактагы үч тамга: түшүм, саны жана маржа боюнча классы (мисалы, «A A C» — көп сатылат, бирок пайдасы аз). Маржа = түшүм − өздүк нарк (Тамактар ▸ Өздүк нарк), арзандатуу жана жеткирүү эсепке алынбайт.');
